#!/bin/bash
# ============================================================
# download_images.sh
# Run this script BEFORE canceling Squarespace to save all
# recipe images locally into the images/ folder.
# ============================================================

set -e
mkdir -p images

echo "Downloading 49 recipe images..."

download() {
  local url="$1"
  local file="$2"
  if [ ! -f "images/$file" ]; then
    echo "  → $file"
    curl -sL "$url" -o "images/$file" || echo "    ⚠️  Failed: $file"
    sleep 0.3  # be polite to the CDN
  else
    echo "  ✓ already exists: $file"
  fi
}

